using System;using System.Linq;using System.IO;using System.Collections.Generic;
public static class BalanceGuards {
 static void Check(bool ok,string m){if(!ok)throw new Exception(m);}
 static double Rate(ForgeProduct p)=> (ForgePricing.Quote(p).SalePrice-ForgeTechnology.Offers.Where(o=>o.Kind==ForgePurchaseKind.Material).Sum(o=>o.Price*p.Data.materials[o.Material]))/p.ProductionSeconds;
 public static string Run(){var lines=new List<string>();ForgeTechnologyChecks.Main();lines.Add("PASS purchase DAG, prices, stock bounds, bundles, speeds, save compatibility");lines.Add(ForgeEconomyChecks.Run());lines.Add(ForgeExpansionChecks.Run());lines.Add(ForgeCampaignChecks.RunChecks());
 string basic="p=1(1)\n2(p,7)\n3(p)\n4(p,3)\n5(p,2)\n";var p=ForgeMvp.Evaluate(basic+"!p").product;foreach(var code in new[]{basic+"6(p)\n7(p)\n!p",basic+"9(p,1)\n9(p,1)\n9(p,1)\n!p",basic.Replace("5(p,2)","6(p)\nb=1(9)\n10(b,p,100,13)\n5(p,b)")+"!p",ForgeCampaignChecks.Final}){var upgraded=ForgeMvp.Evaluate(code);Check(upgraded.error==null&&Rate(upgraded.product)>Rate(p)*1.2,"advanced process must improve net per second by at least 20%");}
 var lucky=ForgeMvp.Evaluate(basic+"777(778(),p)\n!p").product;var star=ForgeMvp.Evaluate(basic.Replace("1(1)","1(7)")+"777(778(),p)\n!p").product;var master=ForgeMvp.Evaluate(ForgeCampaignChecks.Final.Replace("!p","777(778(),p)\n!p")).product;Check(lucky.DiamondReward==1&&star.DiamondReward==2&&master.DiamondReward==3,"quality diamond rewards");Check(p.DiamondReward==0,"no luck no diamonds");var damaged=master.Data;damaged.cracked=true;Check(new ForgeProduct("bad",0,true,master.Traits,0,0,7,damaged).DiamondReward==0,"crack gives no diamonds");
 var cursed=ForgeMvp.Evaluate(basic+"667(p)\n666(p)\n!p").product;Check(ForgePricing.Quote(cursed).SalePrice==ForgePricing.Quote(p).SalePrice*ForgeBalance.CurseMultiplier,"curse multiplier");int destroyed=0;for(uint seed=1;seed<=100;seed++){var e=BlueprintRuntime.Evaluate(basic+"666(p)\n!p",100,10,"risk",seed);if(e.product==null)destroyed++;}Check(destroyed==25,"unprotected curse probability");
 lines.Add("PASS improved process ROI, 1/2/3 diamond tiers, no invalid rewards, curse protection and 25% unprotected destruction");string text=string.Join("\n",lines);Directory.CreateDirectory("Docs/QA/Balance/final");File.WriteAllText("Docs/QA/Balance/final/regression.txt",text);return text;}
}
